SELECT p.id AS position_id, COUNT(e.id) AS events, SUM(e.delivery_status='APPLIED') AS applied, MIN(e.price) AS min_px, MAX(e.price) AS max_px, MIN(e.observed_at) AS first_obs, MAX(e.observed_at) AS last_obs FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at - INTERVAL 5 SECOND AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id ORDER BY p.id;
SELECT p.id AS position_id, e.observed_at, e.price, e.delivery_status, e.outcome_reason FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.closed_at - INTERVAL 90 SECOND AND p.closed_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.observed_at LIMIT 1500;